const manifest = $json.render_manifest_json ?? {};
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Render Manifest Ready Item did not atomically claim a valid content_id.');
}
if (!title) {
  throw new Error('Fetch Next Render Manifest Ready Item did not return title.');
}
if (!Array.isArray(manifest.scenes) || manifest.scenes.length < 4) {
  throw new Error('render_manifest_json is missing scenes.');
}
