  throw new Error('render_manifest_json is missing timeline entries.');
}
const narrationMode = String(manifest?.audio?.narration?.mode ?? '').trim();
const isPerScene = narrationMode === 'per_scene';
if (isPerScene) {
  const narrationScenes = Array.isArray(manifest?.audio?.narration?.scenes) ? manifest.audio.narration.scenes : [];
  if (narrationScenes.length === 0) {
    throw new Error('render_manifest_json has per_scene narration mode but audio.narration.scenes is empty.');
  }
  const missingUrl = narrationScenes.find((s) => !String(s?.storage_url ?? '').trim());
  if (missingUrl) {
    throw new Error('render_manifest_json per_scene narration scene ' + (missingUrl.scene_number ?? '?') + ' is missing storage_url.');
  }
} else {
  if (!String(manifest?.audio?.narration?.storage_url ?? '').trim()) {
    throw new Error('render_manifest_json is missing narration audio (expected audio.narration.storage_url for single-file mode, or audio.narration.mode="per_scene" for per-scene mode).');
  }
}
const parseNumber = (value, fallback) => {
  const parsed = Number.parseFloat(String(value ?? '').trim());
  return Number.isFinite(parsed) ? parsed : fallback;
};
const configuredSyncUrl = String(env.RENDER_WORKER_SYNC_URL || '').trim();
const configuredWorkerUrl = String(env.RENDER_WORKER_URL || '').trim();
const workerUrl = configuredSyncUrl || (configuredWorkerUrl ? configuredWorkerUrl.replace(/\/render\/?$/, '/render-sync') : 'http://render-worker:8080/render-sync');
