const sceneMoods = (Array.isArray(manifest.scenes) ? manifest.scenes : []).flatMap((scene) => [String(scene?.mood ?? '').trim(), String(scene?.music_cue ?? '').trim()]).filter(Boolean);
const scenePromptSummary = (Array.isArray(manifest.scenes) ? manifest.scenes : []).map((scene) => String(scene?.visual_prompt ?? '').trim()).filter(Boolean).slice(0, 6).join(' | ');
const promptProfileSummary = String(sourcePayload.prompt_profile_summary ?? '').trim();
const scriptMusicDirection = String($json.script_music_direction ?? '').trim();
const backgroundMusicDirection = [String(directorJson.global_music_direction ?? '').trim(), String(creativeDefaults.music_mood ?? '').trim(), String(promptProfile?.narration_generation?.background_music_direction ?? '').trim(), scriptMusicDirection].filter(Boolean).join(' | ');
const narrationStyle = [String(directorJson.tts_delivery ?? '').trim(), String(creativeDefaults.narrator_style ?? '').trim(), String(promptProfile?.narration_generation?.narration_style ?? '').trim()].filter(Boolean).join(' | ');
const styleNotes = [String(directorJson.global_visual_style ?? '').trim(), String(directorJson.visual_strategy ?? '').trim(), String(creativeDefaults.visual_strategy ?? '').trim(), String(promptProfile?.storyboard_and_prompts?.visual_style_rules ?? '').trim(), String(promptProfile?.scene_asset_generation?.style_notes ?? '').trim(), String(promptProfile?.post_image_generation?.style_notes ?? '').trim()].filter(Boolean).join(' | ');
