    narration_url: String(scene.narration_url ?? '').trim() || null,
    transition: scene.transition
  })),
  audio: {
    narration_url: isPerScene ? null : (String(manifest.audio?.narration?.storage_url ?? '').trim() || null),
    narration: {
      mode: narrationMode || 'single',
      storage_url: isPerScene ? null : (String(manifest.audio?.narration?.storage_url ?? '').trim() || null)
    },
