  },
  music_context: {
    category: String($json.category ?? 'general').trim() || 'general',
    selected_hook: String($json.selected_hook ?? '').trim(),
    narration_script_excerpt: narrationScript.slice(0, 1500),
    scene_prompt_summary: scenePromptSummary,
    prompt_profile_summary: promptProfileSummary,
    background_music_direction: backgroundMusicDirection,
    narration_style: narrationStyle,
    style_notes: styleNotes,
    scene_moods: sceneMoods,
    script_music_direction: scriptMusicDirection
  },
  subtitles: {
    enabled: false,
    subtitle_lines: Array.isArray(manifest.subtitles?.lines) ? manifest.subtitles.lines : [],
    style: String(manifest.subtitles?.style || env.RENDER_SUBTITLE_STYLE || 'cinematic_center_safe').trim()
  },
  cover: {
