return [{
  json: {
    content_id: contentId,
    title,
    workflow_name: 'wf_render_sync_completion',
    run_started_at: new Date().toISOString(),
    worker_url: workerUrl,
    render_provider: renderProvider,
    request_id: requestId,
    render_request: renderRequest
  }
}];

const requestId = String($json.request_id || '').trim();
const request = $json.render_request ?? {};
const workerUrl = String($json.worker_url || '').trim();
if (!requestId) {
  throw new Error('Prepare Render Request did not provide request_id.');
}
if (!request.content_id) {
  throw new Error('Prepare Render Request did not provide render_request.content_id.');
}
if (!workerUrl) {
  return [{
    json: {
      ...$json,
      render_status: 'failed',
      output_video_url: '',
      cover_image_url: String(request?.cover?.cover_asset_url || '').trim(),
      duration_seconds: 0,
      resolution: '',
      render_log: '',
      error_message: 'Set RENDER_WORKER_SYNC_URL or RENDER_WORKER_URL before running wf_render_sync_completion.'
    }
  }];
}
const response = await helpers.httpRequest({
  method: 'POST',
  url: workerUrl,
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  body: request,
});
const statusCode = Number(response.statusCode ?? 0);
const body = response.body ?? {};
if (statusCode >= 200 && statusCode < 300 && String(body.render_status || '').trim().toLowerCase() === 'success') {
  return [{
    json: {
      ...$json,
      render_status: 'success',
      output_video_url: String(body.output_video_url || '').trim(),
      cover_image_url: String(body.cover_image_url || request?.cover?.cover_asset_url || '').trim(),
      duration_seconds: Number(body.duration_seconds ?? 0),
      resolution: String(body.resolution || '').trim(),
      render_log: String(body.render_log || '').trim(),
      error_message: ''
    }
  }];
}
const errorMessage = String(body.error_message || body.message || JSON.stringify(body) || ('Render worker request failed (' + (statusCode || 'no status') + ').')).trim();
return [{
  json: {
    ...$json,
    render_status: 'failed',
    output_video_url: '',
    cover_image_url: String(body.cover_image_url || request?.cover?.cover_asset_url || '').trim(),
    duration_seconds: Number(body.duration_seconds ?? 0),
    resolution: String(body.resolution || '').trim(),
    render_log: String(body.render_log || '').trim(),
    error_message: errorMessage
  }
}];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Render sync workflow received an invalid content_id: ' + (contentId || '<empty>') + '.');
}
const renderStatus = String($json.render_status ?? '').trim().toLowerCase();
const isSuccess = renderStatus === 'success';
const nextContentStatus = isSuccess ? 'render_complete' : 'render_failed';
const nextRenderStatus = isSuccess ? 'success' : 'failed';
const startedAt = new Date(String($json.run_started_at ?? new Date().toISOString()));
const durationMs = Math.max(0, Date.now() - startedAt.getTime());
const syncSummary = {
  render_status: nextRenderStatus,
  request_id: String($json.request_id ?? '').trim(),
  output_video_url: String($json.output_video_url ?? '').trim(),
  cover_image_url: String($json.cover_image_url ?? '').trim(),
  duration_seconds: Number.isFinite(Number($json.duration_seconds)) ? Number($json.duration_seconds) : 0,
  resolution: String($json.resolution ?? '').trim(),
  error_message: String($json.error_message ?? '').trim()
};
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    next_content_status_sql: nextContentStatus,
    next_render_status_sql: nextRenderStatus,
    output_video_url_sql: String($json.output_video_url ?? '').replaceAll("'", "''"),
    cover_image_url_sql: String($json.cover_image_url ?? '').replaceAll("'", "''"),
    duration_seconds_sql: Number.isFinite(Number($json.duration_seconds)) ? Number($json.duration_seconds) : 0,
    resolution_sql: String($json.resolution ?? '').replaceAll("'", "''"),
    render_log_sql: String($json.render_log ?? '').replaceAll("'", "''"),
    error_message_sql: String($json.error_message ?? '').replaceAll("'", "''"),
    workflow_name_sql: String($json.workflow_name ?? 'wf_render_sync_completion').replaceAll("'", "''"),
    sync_summary_json_sql: JSON.stringify(syncSummary).replaceAll("'", "''"),
    duration_ms_sql: Number.isFinite(durationMs) ? durationMs : 0
  }
}];
